package com.maidaibridge.action.impl;
import com.maidaibridge.action.AbstractMaidAction;import com.maidaibridge.action.ActionContext;import com.maidaibridge.controller.MotionPriority;import net.minecraft.world.entity.Entity;import net.minecraft.world.phys.Vec3;import java.util.UUID;
public final class RetreatAction extends AbstractMaidAction {private final UUID threatId;private final double distance;private Vec3 destination;public RetreatAction(String req,int timeout,UUID threatId,double distance){super(req,"retreat_from",timeout);this.threatId=threatId;this.distance=Math.max(4,distance);}
@Override protected void onStart(ActionContext ctx){Entity threat=ctx.level().getEntity(threatId);if(threat==null){fail("TARGET_GONE");return;}Vec3 away=ctx.maid().position().subtract(threat.position());if(away.lengthSqr()<.01)away=new Vec3(1,0,0);destination=ctx.maid().position().add(away.normalize().scale(distance));destination=new Vec3(destination.x,ctx.maid().getY(),destination.z);if(ctx.motion().acquire(id,MotionPriority.COMBAT,ctx.gameTick()).isEmpty()){fail("MOTION_BUSY");return;}ctx.motion().moveTo(id,ctx.maid(),destination.x,destination.y,destination.z,1.1);}
@Override protected void onTick(ActionContext ctx){if(destination==null)return;if(ctx.maid().position().distanceTo(destination)<=1.5){succeed("RETREATED");ctx.motion().release(id,ctx.maid());}else if(!ctx.maid().getNavigation().isInProgress())ctx.motion().moveTo(id,ctx.maid(),destination.x,destination.y,destination.z,1.1);}
@Override protected void onStop(ActionContext ctx){ctx.motion().release(id,ctx.maid());}}
